import React from "react";

function Form(props) {

    const envioFormulario = (event) => {
        event.preventDefault();
        const form = event.target;

        props.agregarincidencia(
            form.titulo.value,
            form.usuario.value,
            form.descripcion.value,
            form.categoria.value,
            form.nivel.value,
            form.ubicacion.value
        );
    };

    return (
        <div className="card p-4">
            <h2 className="card-title mb-4 text-center">Registrar incidencia</h2>
            <form onSubmit={envioFormulario}>
                {/* Título incidencia */}
                <div>
                    <label className="mb-3 form-label">Título incidencia</label>
                    <input className="mb-3 form-control" type="text" name="titulo" placeholder="Introduce el título" required/><br/><br/>
                </div>

                {/* Usuario */}
                <div>
                    <label className="mb-3 form-label">Usuario</label>
                    <input className="mb-3 form-control" type="text" name="usuario" required/><br/><br/>
                </div>
            </form>
        </div>
    );
}

export default Form;
